import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC 0086 — Shared-store rate limiting for multi-instance deployments","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0086-shared-store-rate-limiting.md"},"headers":[],"relativePath":"rfcs/0086-shared-store-rate-limiting.md","filePath":"rfcs/0086-shared-store-rate-limiting.md"}'),i={name:"rfcs/0086-shared-store-rate-limiting.md"};function r(d,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="rfc-0086-—-shared-store-rate-limiting-for-multi-instance-deployments" tabindex="-1">RFC 0086 — Shared-store rate limiting for multi-instance deployments <a class="header-anchor" href="#rfc-0086-—-shared-store-rate-limiting-for-multi-instance-deployments" aria-label="Permalink to &quot;RFC 0086 — Shared-store rate limiting for multi-instance deployments&quot;">​</a></h1><p><strong>Status:</strong> Partially implemented (task 1.19 shipped; task 2.29 paused before implementation — Edge-runtime/<code>ioredis</code> conflict, see Open questions below)<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> kasunben<br><strong>Scope:</strong> <code>apps/auth/src/auth.ts</code>, <code>runtime/src/rate-limit.ts</code>, <code>runtime/src/brokers/redis.ts</code> (pattern reused, not modified), <code>.env.example</code>, <code>docs/security.md</code>, <code>docs/self-hosting.md</code><br><strong>Incorporated into plan:</strong> Yes — epic tasks 1.19, 2.29.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Sovereign has two independent per-IP rate limiters today, and both are in-memory and single-process by construction:</p><ol><li><strong><code>apps/auth</code>&#39;s better-auth limiter</strong> (<code>apps/auth/src/auth.ts:113-116</code>) — 3 sign-in/sign-up attempts per 10s per IP, 3 password-reset requests per 60s per IP. <code>storage: &#39;memory&#39;</code>.</li><li><strong><code>runtime/middleware.ts</code>&#39;s general per-IP limiter</strong> (<code>runtime/src/rate-limit.ts</code>) — a coarse flood-protection floor over every route the middleware matches, 300 requests/minute per IP by default. Also in-memory, added directly against <code>Map</code>.</li></ol><p>Neither survives an operator scaling past one <code>runtime</code>/<code>auth</code> process — each process holds its own independent bucket state, so a client can get up to N× the intended limit simply by having requests land on different instances, and every instance&#39;s counters reset independently on restart. This is already a known, documented limitation (<code>docs/security.md</code>&#39;s &quot;Login rate limiting&quot; bullet says as much for #1; <code>runtime/src/rate-limit.ts</code>&#39;s doc comment says as much for #2) — this RFC proposes closing it for both, with a different backend for each because their traffic profiles differ by roughly two orders of magnitude.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Sovereign already documents and supports running more than one <code>runtime</code> process/container (PM2 cluster mode, multiple Docker replicas) — see <code>docs/self-hosting.md</code>&#39;s &quot;Notification transport (RFC 0034)&quot; section, which requires operators in that situation to set <code>NOTIFICATION_TRANSPORT=redis</code> because the default in-process <code>EventEmitter</code> transport has no cross-process visibility. Rate limiting has the identical shape of problem and, unlike the notification bell (where a missed real-time push degrades gracefully to the next poll), a rate limiter that silently gets N× weaker under scale-out is a security regression an operator is unlikely to notice — nothing errors, nothing logs, the limit just quietly stops being the limit.</p><p>This matters most for <code>apps/auth</code>: brute-force/credential-stuffing protection on sign-in is the security-critical case rate limiting exists for in the first place, and it&#39;s the one currently most exposed if an operator scales <code>apps/auth</code> without realizing its limiter doesn&#39;t follow.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><strong>better-auth 1.6.25</strong> (the pinned version, <code>apps/auth/package.json:18</code>) ships three built-in rate-limit storage backends, selected via <code>rateLimit.storage</code>: <ul><li><code>&#39;memory&#39;</code> (current default/explicit setting) — an in-process <code>Map</code>.</li><li><code>&#39;database&#39;</code> — reads/writes a <code>rateLimit</code> table through the same adapter better-auth already uses for <code>user</code>/<code>session</code>/<code>account</code>/etc. Atomic increment via a conditional <code>UPDATE ... WHERE count &lt; max</code> (<code>node_modules/better-auth/dist/api/rate-limiter/index.mjs</code>, function <code>createDatabaseStorageWrapper</code>) — correct under concurrent processes, not just concurrent requests in one process.</li><li><code>&#39;secondary-storage&#39;</code> — delegates to whatever object is passed as <code>secondaryStorage</code>, via <code>get</code>/<code>set</code>/<code>increment</code>. If <code>increment</code> is provided, it&#39;s used for atomic consume (<code>getRateLimitStorage</code>, <code>storage === &#39;secondary-storage&#39;</code> branch); Redis&#39;s <code>INCR</code> is the canonical fit.</li><li>There&#39;s also <code>customStorage</code>, a full escape hatch (same file), not needed here.</li></ul></li><li><strong><code>apps/auth</code> manages its own database access directly</strong> (<code>apps/auth/src/db.ts</code>), passing the raw driver (<code>better-sqlite3</code> or <code>pg.Pool</code>) straight to better-auth. better-auth&#39;s own migrator (<code>apps/auth/src/migrate.ts</code>, <code>getMigrations(getAuthOptions())</code>) generates and applies schema for whatever tables its own options imply — this already runs on every startup. Turning on <code>storage: &#39;database&#39;</code> needs no hand-written schema or migration: the <code>rateLimit</code> table appears in better-auth&#39;s own generated migration set as soon as the option is set, the same way <code>user</code>/<code>session</code>/<code>account</code> already do.</li><li><strong><code>runtime</code> already has <code>ioredis</code> as a dependency</strong> and an established Redis integration pattern: <code>runtime/src/brokers/redis.ts</code>&#39;s <code>RedisBroker</code>, gated behind <code>REDIS_URL</code> (<code>docs/self-hosting.md</code>&#39;s &quot;Notification transport&quot; section, <code>.env.example:230-235</code>), with <code>ioredis</code> imported lazily via <code>require()</code> so the module import cost is paid only when Redis mode is actually selected. <code>apps/auth</code> does <strong>not</strong> currently depend on <code>ioredis</code>.</li><li><strong><code>runtime/src/rate-limit.ts</code></strong> (added by the general per-IP limiter, landed just before this RFC) is a fixed-window bucket keyed by client IP, same shape as <code>directory.ts</code>/<code>plugin-mailer.ts</code>&#39;s existing per-feature limiters, but held in a bare in-process <code>Map</code> with no storage abstraction — there&#39;s currently nothing to swap out.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><p>Two independent changes, matched to each limiter&#39;s traffic profile.</p><h3 id="apps-auth-switch-to-storage-database" tabindex="-1"><code>apps/auth</code>: switch to <code>storage: &#39;database&#39;</code> <a class="header-anchor" href="#apps-auth-switch-to-storage-database" aria-label="Permalink to &quot;`apps/auth`: switch to `storage: &#39;database&#39;`&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// apps/auth/src/auth.ts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rateLimit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NODE_ENV</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;test&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;database&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>Sign-in/sign-up/reset traffic is inherently low-volume (a handful of attempts per user per session at most) — a database round-trip per attempt is negligible overhead, and it&#39;s the same database (SQLite or Postgres) <code>apps/auth</code> already talks to for every other request, so this adds no new infrastructure, no new dependency, and no new failure mode beyond &quot;the auth database is unavailable,&quot; which is already fatal to sign-in regardless. It also means the fix scales itself correctly: an operator who&#39;s outgrown SQLite&#39;s single-file model has already moved to Postgres for the primary auth data, and the rate limiter&#39;s correctness now rides on that same decision instead of needing a second one.</p><p>No new env var. <code>.env.example</code>/<code>docs/security.md</code> get a wording update (see &quot;Docs impact&quot; below) since the &quot;in-memory per process... sufficient for single-instance deployments&quot; caveat stops being true.</p><h3 id="runtime-s-general-per-ip-limiter-optional-redis-backend-mirroring-notification-transport" tabindex="-1"><code>runtime</code>&#39;s general per-IP limiter: optional Redis backend, mirroring <code>NOTIFICATION_TRANSPORT</code> <a class="header-anchor" href="#runtime-s-general-per-ip-limiter-optional-redis-backend-mirroring-notification-transport" aria-label="Permalink to &quot;`runtime`&#39;s general per-IP limiter: optional Redis backend, mirroring `NOTIFICATION_TRANSPORT`&quot;">​</a></h3><p>Unlike <code>apps/auth</code>, this limiter runs on <strong>every</strong> matched request, not just auth attempts — routing that through the primary platform database would add a write to shared, latency-sensitive infrastructure on every page load and API call, which is the wrong trade. Redis&#39;s <code>INCR</code>/<code>PEXPIRE</code> is built for exactly this access pattern and is already optional, established infrastructure in this codebase.</p><p>Proposed shape, following the <code>NOTIFICATION_TRANSPORT</code> precedent closely enough to be immediately familiar to anyone who&#39;s already configured that:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SOVEREIGN_RATE_LIMIT_STORE=memory|redis   # default: memory</span></span></code></pre></div><ul><li><code>memory</code> (default): today&#39;s behavior, unchanged — the existing <code>Map</code> in <code>runtime/src/rate-limit.ts</code>. Zero-config, correct for the default single-container topology.</li><li><code>redis</code>: <code>checkGlobalRateLimit</code> delegates to a small Redis-backed bucket (new sibling file, e.g. <code>runtime/src/rate-limit-redis.ts</code>) using the same lazy-<code>require(&#39;ioredis&#39;)</code> pattern as <code>RedisBroker</code>, keyed the same way (<code>sv:ratelimit:&lt;ip&gt;</code>), using <code>INCR</code> + <code>PEXPIRE NX</code> (or a small Lua script for atomicity — better-auth&#39;s own database path is a useful reference for how much atomicity actually matters here) instead of the in-memory <code>Map</code>. Reuses <code>REDIS_URL</code> — no second Redis connection string.</li><li>Requires <code>REDIS_URL</code> to be set when <code>SOVEREIGN_RATE_LIMIT_STORE=redis</code>; fails closed at startup (consistent with this codebase&#39;s &quot;no secrets with defaults&quot; posture applied to required config, not just secrets) rather than silently falling back to memory, since a silent fallback here is exactly the &quot;looks configured, isn&#39;t&quot; failure mode this RFC exists to avoid.</li></ul><p><code>docs/self-hosting.md</code>&#39;s existing &quot;If you run more than one runtime container or process, you must set...&quot; callout gets a second bullet alongside <code>NOTIFICATION_TRANSPORT=redis</code> for this.</p><h3 id="why-not-one-unified-store-for-both" tabindex="-1">Why not one unified store for both <a class="header-anchor" href="#why-not-one-unified-store-for-both" aria-label="Permalink to &quot;Why not one unified store for both&quot;">​</a></h3><p>Considered — a single new abstraction (e.g. <code>packages/rate-limit-store</code> or an addition to <code>packages/db</code>) exposing <code>get</code>/<code>set</code>/<code>increment</code> with two backends, consumed by both <code>apps/auth</code> (via better-auth&#39;s <code>customStorage</code>) and <code>runtime/src/rate-limit.ts</code>. Rejected for this RFC: <code>apps/auth</code> deliberately does not depend on <code>packages/db</code> (<code>apps/auth/src/db.ts:37-38</code>, &quot;mirrors packages/db; not imported, as the auth server intentionally does not depend on packages/db&quot;) — introducing a new shared package both apps depend on cuts against that existing boundary for a feature where the two sides don&#39;t actually want the same backend anyway (one wants the primary DB, one wants Redis). Two small, independent changes that each reuse an existing in-house pattern is less total surface than one new cross-app abstraction. Worth revisiting only if a third rate limiter shows up with its own shared-store need.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong><code>apps/auth</code> also on Redis (<code>secondary-storage</code>)</strong> — only sensible if the instance is already running Redis for notifications; otherwise it&#39;s new required infrastructure for a low-volume path that the database backend already solves for free. Would need <code>ioredis</code> added as a new <code>apps/auth</code> dependency (currently <code>runtime</code>-only). Not worth the extra moving part when <code>storage: &#39;database&#39;</code> is a one-line, zero-new-dependency fix.</li><li><strong>Leave both as documented, accepted limitations</strong> — the status quo. Rejected because Sovereign already treats &quot;more than one process&quot; as a supported, if advanced, deployment shape (RFC 0034), and a rate limiter that quietly weakens under exactly that shape is worse than one that requires explicit opt-in configuration to scale correctly.</li><li><strong>Make <code>runtime</code>&#39;s limiter always require Redis once any scaling is detected</strong> — no reliable way to auto-detect &quot;more than one process&quot; from inside one process; matches why <code>NOTIFICATION_TRANSPORT</code> is also an explicit operator choice, not auto-detected.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><p><strong>Blocking, found during implementation (workstream 0017 leg 5):</strong><code>runtime/middleware.ts</code> executes in Next.js&#39;s <strong>Edge runtime</strong>, not the Node runtime — confirmed by the file&#39;s own existing comment at the dev-mode check (&quot;Edge runtime cannot write to the DB, so audit logging is done via <code>console.log</code>&quot;), and by the fact that <code>RedisBroker</code> (<code>runtime/src/brokers/redis.ts</code>) is only ever instantiated from Node-runtime route handlers (<code>runtime/app/api/admin/health/route.ts</code>), never from middleware. <code>ioredis</code> depends on Node&#39;s <code>net</code>/<code>tls</code> built-ins for raw TCP sockets (confirmed in its own source, <code>ioredis/built/connectors/StandaloneConnector.js</code>), which the Edge runtime does not provide. The &quot;same lazy <code>require(&#39;ioredis&#39;)</code> pattern as <code>RedisBroker</code>&quot; proposed above therefore cannot work as written — that pattern is only valid from a Node-runtime call site, and <code>checkGlobalRateLimit</code>/<code>clientIp</code> are called directly from middleware. This RFC did not anticipate the runtime split when originally drafted.</p><p>Three ways to close this gap, none free:</p><ol><li><strong>Enable Next.js Node.js Middleware</strong> (<code>experimental.nodeMiddleware</code> + <code>export const runtime = &#39;nodejs&#39;</code> on <code>middleware.ts</code>) so <code>ioredis</code> can load. Correct long-term fix, but changes the runtime for the <em>entire</em> middleware file, not just the rate limiter — every existing Edge-specific accommodation (the DB-write avoidance, the <code>console.log</code>-only dev-mode audit path, CSP/nonce handling) would need re-verification under the new runtime. This is platform-wide blast radius that deserves its own task and review, not a side effect of a &quot;small, low-risk&quot; rate-limiting leg.</li><li><strong>A fetch/HTTP-based Redis client</strong> (e.g. Upstash&#39;s REST protocol) usable from Edge. Rejected as the default path: it&#39;s a different protocol from plain <code>REDIS_URL</code>, and the self-hosted Redis this platform already documents (the Docker Compose service backing <code>NOTIFICATION_TRANSPORT=redis</code>) doesn&#39;t expose a REST endpoint — adopting this would mean a second, incompatible Redis integration story instead of the &quot;reuse <code>REDIS_URL</code>, no second connection string&quot; goal stated above.</li><li><strong>Route the check through an internal Node-runtime call</strong> from middleware. Adds a network hop to nearly every request this limiter covers (the whole middleware matcher), a real latency cost for what&#39;s meant to be a lightweight flood-protection floor.</li></ol><p><strong>Not resolved by this RFC.</strong> Task 2.29 is paused pending a deliberate choice among the above (most likely option 1, scoped as its own task with its own review, given its blast radius) — see the epic task&#39;s correction note in <code>docs/epics/platform-shell.md</code>. Task 1.19 (<code>apps/auth</code>) has no such issue — better-auth&#39;s <code>storage: &#39;database&#39;</code> runs in the Node runtime already and is unaffected.</p></li><li><p>Exact atomicity mechanism for the Redis-backed general limiter (<code>INCR</code> + conditional <code>PEXPIRE</code> vs. a small Lua script) — a leg-detail item, not a design blocker; better-auth&#39;s own <code>secondary-storage</code> branch (<code>getRateLimitStorage</code>, <code>ctx.options.secondaryStorage.increment</code>) is a reasonable reference implementation to match.</p></li><li><p>Whether <code>SOVEREIGN_RATE_LIMIT_STORE=redis</code> without <code>REDIS_URL</code> set should fail at startup (proposed above) or fail the first request — startup is preferred (fail fast, matches &quot;no secrets with defaults&quot;) but worth confirming against how <code>NOTIFICATION_TRANSPORT=redis</code> currently handles the same missing-<code>REDIS_URL</code> case, for consistency.</p></li><li><p>Whether <code>apps/auth</code>&#39;s switch to <code>storage: &#39;database&#39;</code> needs a regression test asserting the <code>rateLimit</code> table actually appears after <code>runAuthMigrations()</code> runs, or whether better-auth&#39;s own test coverage of that path is trusted as-is.</p></li></ul><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Documentation-first. Two small, independently shippable changes once scheduled:</p><ol><li><code>apps/auth</code>&#39;s <code>storage: &#39;database&#39;</code> flip — smaller of the two, no new dependency, could ship alone ahead of the Redis-backed <code>runtime</code> change if prioritized separately. <strong>Shipped</strong> (workstream 0017 leg 4, task 1.19).</li><li><code>runtime</code>&#39;s <code>SOVEREIGN_RATE_LIMIT_STORE</code> option — adds a new sibling module and one new env var; <code>.env.example</code>/<code>docs/self-hosting.md</code> need the docs-parity updates the existing convention requires. <strong>Paused</strong> (workstream 0017 leg 5, task 2.29) — blocked on the Edge-runtime/<code>ioredis</code> conflict above; needs a scoped follow-up decision before implementation resumes.</li></ol><p>No SDK, manifest, or published-package surface changes. No breaking change to either limiter&#39;s default behavior — <code>memory</code> stays the default for <code>runtime</code>, and <code>apps/auth</code>&#39;s switch to <code>database</code> storage doesn&#39;t change its externally-visible 429/<code>X-Retry-After</code> behavior, only where the counters live.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>August 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>August 2026</td><td>Task 1.19 shipped (<code>apps/auth</code> <code>storage: &#39;database&#39;</code>). Task 2.29 paused before implementation: <code>runtime/middleware.ts</code> runs in the Edge runtime, which cannot load <code>ioredis</code> (Node <code>net</code>/<code>tls</code>-dependent) — a design gap this RFC&#39;s original Redis proposal didn&#39;t account for. Added to Open questions; adoption path updated. No code shipped for 2.29 yet.</td></tr></tbody></table>',36)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
